import { Card, CardBody, CardTitle, Container, Row, Col } from "reactstrap";
import { useEffect, useState } from "react";
import { db, auth } from "../../firebase";  // Ensure correct import path

import { doc, getDoc } from "firebase/firestore";

const Header = () => {
  const [carbonData, setCarbonData] = useState({
    footprint: 0,
    credits: 0,
    progress: 0,
    rank: 0,
    changes: {
      monthly: 0,
      weekly: 0,
      daily: 0
    }
  });

  // Calculate emission factors (adjust these according to your metrics)
  const emissionFactors = {
    electricity: 0.5, // kg CO₂ per kWh
    transportation: 0.2, // kg CO₂ per km
    waste: 0.1 // kg CO₂ per kg
  };

  useEffect(() => {
    const fetchUserData = async () => {
      const user = auth.currentUser;
      if (user) {
        const docRef = doc(db, "users", user.uid);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          const userData = docSnap.data();

          // Calculate carbon footprint
          const footprint = (
            (userData.electricity || 0) * emissionFactors.electricity +
            (userData.transportation || 0) * emissionFactors.transportation +
            (userData.waste || 0) * emissionFactors.waste
          );

          // Calculate other metrics
          const credits = footprint * 0.1; // 10% of footprint as credits
          const progress = ((footprint / 1000) * 100); // Progress towards 1000kg goal
          const rank = calculateRank(footprint); // Implement your ranking logic

          setCarbonData({
            footprint: footprint.toFixed(2),
            credits: credits.toFixed(2),
            progress: progress.toFixed(2),
            rank,
            changes: userData.changes || { monthly: 0, weekly: 0, daily: 0 }
          });
        }
      }
    };

    fetchUserData();
  }, []);

  // Dummy rank calculation - replace with your actual logic
  const calculateRank = (footprint) => {
    return Math.floor(Math.random() * 100); // Example random rank
  };

  return (
    <div className="header bg-gradient-info pb-8 pt-5 pt-md-8">
      <Container fluid>
        <div className="header-body">
          <Row>
            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Carbon Footprint (kg CO₂)
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">
                        {carbonData.footprint}
                      </span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-danger text-white rounded-circle shadow">
                        <i className="fas fa-chart-bar" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className={`text-${carbonData.changes.monthly >= 0 ? 'success' : 'danger'} mr-2`}>
                      <i className={`fa fa-arrow-${carbonData.changes.monthly >= 0 ? 'up' : 'down'}`} /> 
                      {Math.abs(carbonData.changes.monthly)}%
                    </span>{" "}
                    <span className="text-nowrap">Since last month</span>
                  </p>
                </CardBody>
              </Card>
            </Col>

            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Carbon Credits Earned
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">{carbonData.credits}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-warning text-white rounded-circle shadow">
                        <i className="fas fa-chart-pie" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className={`text-${carbonData.changes.weekly >= 0 ? 'success' : 'danger'} mr-2`}>
                      <i className={`fas fa-arrow-${carbonData.changes.weekly >= 0 ? 'up' : 'down'}`} /> 
                      {Math.abs(carbonData.changes.weekly)}%
                    </span>{" "}
                    <span className="text-nowrap">Since last week</span>
                  </p>
                </CardBody>
              </Card>
            </Col>

            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Carbon Reduction Progress (%)
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">{carbonData.progress}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-yellow text-white rounded-circle shadow">
                        <i className="fas fa-users" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className={`text-${carbonData.changes.daily >= 0 ? 'success' : 'warning'} mr-2`}>
                      <i className={`fas fa-arrow-${carbonData.changes.daily >= 0 ? 'up' : 'down'}`} /> 
                      {Math.abs(carbonData.changes.daily)}%
                    </span>{" "}
                    <span className="text-nowrap">Since yesterday</span>
                  </p>
                </CardBody>
              </Card>
            </Col>

            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Rank
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">#{carbonData.rank}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-info text-white rounded-circle shadow">
                        <i className="fas fa-percent" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className="text-success mr-2">
                      <i className="fas fa-arrow-up" /> {carbonData.changes.monthly}%
                    </span>{" "}
                    <span className="text-nowrap">Since last month</span>
                  </p>
                </CardBody>
              </Card>
            </Col>
          </Row>
        </div>
      </Container>
    </div>
  );
};

export default Header;
